package cn.zhuatech.documentai; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import java.util.regex.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DocumentAiApiIntegrationTests{@Autowired MockMvc mvc;String token;@BeforeEach void login()throws Exception{String j=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"operator\",\"password\":\"Demo@2026\"}")).andReturn().getResponse().getContentAsString();Matcher m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(j);if(!m.find())throw new AssertionError();token=m.group(1);}@Test void extracts()throws Exception{mvc.perform(post("/api/ai/document/extract").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"documentNo\":\"DOC-1\",\"documentType\":\"合同\",\"ocrConfidence\":98,\"layoutConfidence\":95,\"sourceTrustScore\":96,\"totalFields\":18,\"missingRequiredFields\":0,\"signatureRequired\":true,\"signatureDetected\":true,\"duplicateFingerprint\":false}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.decision").value("AUTO_ACCEPT"));}}
